import{_ as s,c as n,o as i,a2 as a}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"Choix de confidentialité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy-choices.md","filePath":"fr/guide/privacy-choices.md","lastUpdated":1793163976000}'),o={name:"fr/guide/privacy-choices.md"};function t(r,e,l,c,d,u){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="choix-de-confidentialite" tabindex="-1">Choix de confidentialité <a class="header-anchor" href="#choix-de-confidentialite" aria-label="Permalink to &quot;Choix de confidentialité&quot;">​</a></h1><p>NueZip est une application entièrement hors ligne. Puisque toutes vos données restent sur votre appareil, nous ne collectons, ne vendons ni ne partageons aucune information personnelle.</p><h2 id="donnees-conservees-localement" tabindex="-1">Données conservées localement <a class="header-anchor" href="#donnees-conservees-localement" aria-label="Permalink to &quot;Données conservées localement&quot;">​</a></h2><p>NueZip stocke toutes les données localement sur votre Mac :</p><ul><li>Préférences et configuration de l&#39;application</li><li>Liste des fichiers récents</li><li>Journaux de débogage (si activés)</li><li>Mots de passe stockés dans le trousseau (si vous choisissez de les enregistrer)</li></ul><p>Aucune de ces données n&#39;est téléversée vers un serveur.</p><h2 id="vos-droits" tabindex="-1">Vos droits <a class="header-anchor" href="#vos-droits" aria-label="Permalink to &quot;Vos droits&quot;">​</a></h2><p>Puisque NueZip ne collecte ni ne stocke de données personnelles sur nos serveurs, il n&#39;y a aucune donnée personnelle pour nous à accéder, supprimer ou transférer. Toutes vos données peuvent être gérées directement dans l&#39;application ou en supprimant le dossier conteneur de l&#39;application :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span></code></pre></div><h2 id="ne-pas-vendre" tabindex="-1">Ne pas vendre <a class="header-anchor" href="#ne-pas-vendre" aria-label="Permalink to &quot;Ne pas vendre&quot;">​</a></h2><p>NueZip ne vend aucune information personnelle. Nous n&#39;utilisons aucune analyse tierce, publicité ou service de suivi de quelque nature que ce soit.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Si vous avez des questions sur les choix de confidentialité, ouvrez un problème à l&#39;adresse : <code>https://github.com/nuezip/nuezip/issues</code></p>',13)])])}const v=s(o,[["render",t]]);export{h as __pageData,v as default};
